class Solution {
  public long nthSmallest(long n, int k) {
    long[][] c = new long[52][52];
    for (int i = 0; i < 52; i++) {
      c[i][0] = 1;
      for (int j = 1; j <= i; j++) c[i][j] = c[i - 1][j - 1] + (j <= i - 1 ? c[i - 1][j] : 0);
    }
    long result = 0;
    for (int i = k; i >= 1; i--) {
      int p = i - 1;
      while (p + 1 < 51 && c[p + 1][i] < n) p++;
      result |= 1L << p;
      n -= c[p][i];
    }
    return result;
  }
}
